// Design round #78 — the stub library the Profile prototypes share. Generated
// from the shape of the owner's real Library (78 sessions over 2023–2026, 70
// rated, one not finished, ~50 Want to read), plus three re-reads, three
// current reads and per-day progress (reading_progress_days) for the current
// reads and the last finished one. Prototype data: nothing in production
// imports it. Regenerate with /tmp/libellus-78/wip/gen.mjs.
import type { CoverColors } from '~/data/books'

export type StubBook = {
  key: string
  title: string
  authors: string[]
  /** The edition's page count (books.page_count), null when the source had none. */
  pages: number | null
  cover: string | null
  thumbhash: string | null
  colors: CoverColors | null
}
/** A reading session: open while `outcome` is null. Rating in quarter stars 1–20. */
export type StubSession = {
  book: string
  started: string | null
  ended: string | null
  outcome: 'finished' | 'abandoned' | null
  rating: number | null
  page?: number | null
  percent?: number | null
}
/** One row of reading_progress_days: where the day began and ended. */
export type StubDay = { book: string; day: string; from: number; to: number; unit?: 'percent' }

/** The prototypes' today: the stub is pinned to it, so every figure is stable. */
export const TODAY = '2026-10-04'

